		p1:WaitForChild("Stats")
		p1:WaitForChild("Config")

		local Ability1 = p1:WaitForChild("Abilities"):FindFirstChild("Ability1")

		if not Ability1 or p1:GetAttribute("HasToggleAbility") then
			return
		end

		local Cooldown = Ability1:WaitForChild("Cooldown")

		Ability1:WaitForChild("CurrentCooldown")
		Cooldown.Value = math.floor(Cooldown.Value * 0.92)

		if not (Cooldown.Value <= 5) then
			return
		end

		Cooldown.Value = 5
	end,
	RemoveTrinket = function(p1) --[[ RemoveTrinket | Line: 40 ]]
		local Trinkets = p1:WaitForChild("Trinkets")
		local Stats = p1:WaitForChild("Stats")

		Stats:WaitForChild("WalkSpeed")
		Stats:WaitForChild("RunSpeed")

		local Trinket1 = Trinkets:FindFirstChild("Trinket1")
		local Trinket2 = Trinkets:FindFirstChild("Trinket2")

		if not (Trinket1 and Trinket2) then
